import { Logout } from '@mesx/common-ui-lib';
import { createRouter, createWebHistory } from 'vue-router';
import CustomAttributesView from '../modules/custom-attributes/views/CustomAttributes.vue';
import Unauthorized from '../modules/unauthorized/views/Unauthorized.vue';
import homepageShortcuts from '@/modules/homepage-shortcuts/views/homepage-shortcuts.vue';
import { useProfileStore } from '@/store/user-auth-store';
import appLogger from '@/utils/logger/app-logger.ts';

const appRedirectUri = import.meta.env.APP_REDIRECT_URI;
let appBasePath: string | undefined;
if (appRedirectUri) {
  const parts = appRedirectUri.split('/');
  appBasePath = parts.pop();
}
const routes = [
  {
    component: Logout,
    name: 'Logout',
    path: '/logout',
    props: {
      onLoginAgain: (): void => {
        const userAuth = useProfileStore();
        userAuth.initializeAuthentication();
        router.push('/ume-ui');
      },
    },
  },
  {
    component: CustomAttributesView,
    meta: { requiresAuth: true, title: 'Custom Attributes Management' },
    name: 'CustomAttributes',
    path: '/ume-ui/',
    props: true,
  },
  {
    component: homepageShortcuts,
    meta: { requiresAuth: true, title: 'Homepage Shortcuts' },
    name: 'Homepage Shortcuts',
    path: '/ume-ui/HomepageShortcuts',
    props: true,
  },
  {
    component: Unauthorized,
    name: 'Unauthorized',
    path: `/${appBasePath}/unauthorized`,
  },
];

export const router = createRouter({
  history: createWebHistory(),
  routes,
});
router.beforeEach(async (to, _from, next) => {
  if (to.meta.title) {
    document.title = `MESX.0 - ${to.meta.title as string}`;
  }
  // Check if the route requires authentication
  const userAuth = useProfileStore();
  if (to.meta.requiresAuth) {
    try {
      await userAuth.authenticateUser();
      const user = await userAuth.getUser();
      if (user) {
        await userAuth.fetchUserAttributes();
        await userAuth.authorizeUser();
      } else {
        // Handle the case where the user is null
        console.error('User not found');
        return next(`/${appBasePath}/unauthorized`); // Return is added here
      }

      // Proceed to the route
      return next(); // Explicit return added
    } catch (error) {
      appLogger.error(`Error during authentication or authorization: ${error}`);
      return next(`/${appBasePath}/unauthorized`); // Return is added here
    }
  } else {
    return next(); // Explicit return for non-authenticated routes
  }
});

