import { defineStore } from 'pinia';
import { CustomAttributesMappingByUser } from '@/modules/custom-attributes/dto/custom-attributes-mapping-response';
import { CustomAttributesResponse } from '@/modules/custom-attributes/dto/custom-attributes-response';
import { CustomAttributePayload } from '@/modules/custom-attributes/dto/save-custom-attribute-payload.dto';
import * as api from '@/modules/custom-attributes/service/api';

export const useCustomAttributeStore = defineStore({
  actions: {
    async deleteCustomAttribute(userAttributeId: number): Promise<boolean> {
      try {
        const userId = this.getUserId;
        await api.deleteCustomAttribute(userAttributeId, userId);
        this.deleteCustomAttributeFromLocalStorage([userAttributeId]);
        return true;
      } catch (error) {
        // Handle the error
        console.error('Failed to delete custom attribute:', error);
        return false;
      }
    },

    deleteCustomAttributeFromLocalStorage(ids: Array<number>) {
      const remainingAttributes = this.removeIdsAndTransform(ids);
      const attributesToStore =
        remainingAttributes && !this.isEmptyObject(remainingAttributes)
          ? { userAttributes: remainingAttributes }
          : remainingAttributes;

      localStorage.setItem('userAttributes', JSON.stringify(attributesToStore));
    },
    async deleteCustomMultipleAttributes(
      userAttributesIds: string,
    ): Promise<boolean> {
      try {
        const userId = this.getUserId;
        await api.deleteCustomMultipleAttributes(userAttributesIds, userId);
        const userAttributeIdsArray: Array<number> = userAttributesIds
          .split(',')
          .map(Number);
        this.deleteCustomAttributeFromLocalStorage(userAttributeIdsArray);
        return true;
      } catch (error) {
        console.error('Failed to delete custom attributes:', error);
        return false;
      }
    },

    async getCustomAttributes() {
      try {
        this.customAttributes = await api.getCustomAttributes();
      } catch (error) {
        console.error('Failed to fetch custom attribute:', error);
      }
    },
    async getCustomAttributesMappingByUser() {
      try {
        const userId = this.getUserId;
        this.customAttributesMapping =
          await api.getCustomAttribueMappingByUser(userId);
      } catch (error) {
        console.error('Failed to fetch custom attributes mapping:', error);
      }
    },
    async resolveUserPlants() {
      try {
        this.plants = await api.resolveUserPlants();
      } catch (error) {
        console.error('Failed to fetch plants:', error);
      }
    },
    isEmptyObject(object: { [key: string]: string }): boolean {
      return (
        object &&
        Object.keys(object).length === 0 &&
        object.constructor === Object
      );
    },
    mergeAttributes(
      existingAttributes: Array<CustomAttributesMappingByUser>,
      newAttributes: Array<CustomAttributesMappingByUser>,
    ): Array<CustomAttributesMappingByUser> {
      // Create a map to merge by userAttributeId
      const attributeMap = new Map<number, CustomAttributesMappingByUser>();
      // Add existing attributes to the map
      for (const attribute of existingAttributes)
        attributeMap.set(attribute.userAttributeId, attribute);
      // Add new attributes to the map (this will overwrite duplicates based on userAttributeId)
      for (const attribute of newAttributes)
        attributeMap.set(attribute.userAttributeId, attribute);
      // Convert map back to array
      return [...attributeMap.values()];
    },
    removeIdsAndTransform(idsToRemove: Array<number>): {
      [key: string]: string;
    } {
      // Filter out the attributes with specified IDs
      const filteredAttributes = this.customAttributesMapping.filter(
        (attribute) => !idsToRemove.includes(attribute.userAttributeId),
      );
      this.customAttributesMapping = filteredAttributes;
      // Transform the remaining attributes to storage format
      return this.transformAttributesToStorageFormat(filteredAttributes);
    },

    async saveCustomAttribute(
      customAttributes: Array<CustomAttributesMappingByUser>,
    ): Promise<boolean> {
      try {
        const userId = this.getUserId;
        const payload: Array<CustomAttributePayload> = customAttributes.map(
          (attribute) => ({
            userAttributeId: attribute.userAttributeId,
            value: attribute.value,
          }),
        );
        await api.saveCustomAttribute(payload, userId);
        this.updateLocalStorage(customAttributes);
        return true;
      } catch (error) {
        // Handle the error, e.g., log it or show a user-friendly message
        console.error('Failed to save custom attributes:', error);
        return false;
      }
    },
    transformAttributesToStorageFormat(
      attributes: Array<CustomAttributesMappingByUser>,
    ): {
      [key: string]: string;
    } {
      const transformed: { [key: string]: string } = {};
      for (const attribute of attributes) {
        transformed[attribute.userAttributeName] = attribute.value;
      }
      return transformed;
    },
    updateLocalStorage(customAttributes: Array<CustomAttributesMappingByUser>) {
      const mergedAttributes = this.mergeAttributes(
        this.customAttributesMapping,
        customAttributes,
      );

      // Update the store
      this.customAttributesMapping = mergedAttributes;
      const transformedAttributes =
        this.transformAttributesToStorageFormat(mergedAttributes);
      localStorage.setItem(
        'userAttributes',
        JSON.stringify({ userAttributes: transformedAttributes }),
      );

      const plantId = transformedAttributes.plant;
      if (plantId) {
        api.getTimezoneByPlantId(Number(plantId)).then((timezone) => {
          if (timezone) {
            localStorage.setItem('timezone', timezone);
          } else {
            localStorage.setItem('timezone', 'utc');
          }
        });
      }
    },
  },
  getters: {
    getUserId() {
      return Number(localStorage.getItem('userId'));
    },
  },
  id: 'customAttributeStore',
  state: () => ({
    customAttributes: [] as Array<CustomAttributesResponse>,
    customAttributesMapping: [] as Array<CustomAttributesMappingByUser>,
    plants: [] as Array<string>,
  }),
});

import {
  authorizeUser,
  AuthConfigService,
  ApiService,
  UserAttributesManager,
} from '@mesx/common-ui-lib';
import { WebStorageStateStore } from 'oidc-client';
import { defineStore } from 'pinia';
import { useRouter } from 'vue-router';
import { getUser, User } from '../Auth/user-service.ts';
import { useUserStore } from './user-store.ts';
import { configuration } from '@/Auth/configuration.ts';
import { AuthConfigDTO } from '@/types/auth.config.dto.ts';
import appLogger from '@/utils/logger/app-logger';

interface State {
  profile: string;
  user: User | undefined;
  userAttributes: { [key: string]: string };
  managedBy: string;
}

const authconfig = new AuthConfigDTO(
  configuration.getAuthority(),
  configuration.getClientId(),
  configuration.getRedirectUri(),
  configuration.getResponseType(),
  configuration.getScopes(),
  new WebStorageStateStore({ store: window.sessionStorage }),
  configuration.getAccessTokenExpiringNotificationTime(),
);
const umeBaseUrl = import.meta.env.UME_API_URL;
const appName = 'CUSTOM-ATTRIBUTE';
let tokenEnvironment = import.meta.env.TOKEN;
tokenEnvironment =
  tokenEnvironment === 'PING_FEDERATE'
    ? sessionStorage.getItem('id_token')
    : tokenEnvironment;
const redirectUri = import.meta.env.APP_REDIRECT_URI;
let appBasePath: string;
if (redirectUri) {
  const parts = redirectUri.split('/');
  appBasePath = parts.pop();
}
const authService = new AuthConfigService(authconfig);
const apiService = new ApiService(umeBaseUrl, tokenEnvironment, appName);
const userAttributesManager = new UserAttributesManager(apiService);
export const useProfileStore = defineStore('user', {
  actions: {
    async authenticateUser() {
      const useUser = useUserStore();
      const user = await getUser();
      if (!user) {
        appLogger.error('User not found');
        return;
      }
      if (user) {
        const fetchedUser = await apiService.getUserByEmail(user.profile.email);
        if (fetchedUser) {
          localStorage.setItem('userId', fetchedUser.userId);
          await apiService.updateUserLastLoginByEmail(
            fetchedUser.email,
            new Date(),
          );
        } else {
          const userDetails = {
            firstName: user.profile.given_name,
            lastName: user.profile.family_name,
            email: user.profile.email,
            lastLogin: new Date(),
          };
          await apiService.saveUser(userDetails);
        }
        useUser.setProfile(
          `${user.profile.given_name} ${user.profile.family_name}`,
        );
      }
    },
    async authorizeUser() {
      const router = useRouter();
      const user = await getUser();
      if (user) {
        const roleNamesString = user.profile.groups.join(',');
        await authorizeUser(apiService, roleNamesString, router, appBasePath);
      }
    },
    async fetchUserAttributes() {
      try {
        const attributes = await userAttributesManager.loadAttributes();
        const userAttributes =
          userAttributesManager.transformAttributesToStorageFormat(attributes);
        if (userAttributes) {
          this.userAttributes = { ...userAttributes };
        } else {
          appLogger.warn('No user attributes found.');
        }
      } catch (error) {
        appLogger.error(`Error fetching user attributes: ${error}`);
      }
    },
    async getUser(): Promise<User | undefined> {
      if (this.user) {
        return this.user;
      }
      const user = await getUser();
      if (user) {
        this.user = user;
      }
      return user;
    },
    async initializeAuthentication() {
      const router = useRouter();
      await authService.initializeAuthentication(router);
    },
    async isAuthenticated(): Promise<boolean> {
      return authService.isAuthenticated();
    },
    async logout() {
      try {
        await authService.logout();
        localStorage.removeItem('userAuth');
        localStorage.removeItem('userAttributes');
      } catch {
        appLogger.error('Log out failed');
      }
    },
  },

  persist: {
    key: 'userAttributes',
    paths: ['userAttributes'],
  },
  state: (): State => ({
    managedBy: '',
    profile: '',
    userAttributes: {} as { [key: string]: string },
    user: undefined as User | undefined,
  }),
});

